<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { ElMessage,ElMessageBox, ElSelect, ElOption, ElDialog, ElRate, ElDescriptions, ElDescriptionsItem } from 'element-plus'
import PlatformLayout from '../components/PlatformLayout.vue'
import PrivatePhoto from '../components/PrivatePhoto.vue'
import { useApi,money,date,states,type Row } from '../composables/useApi'
const {api,act,auth}=useApi(),orders=ref<Row[]>([]),filter=ref(''),loading=ref(false),busy=ref(false),error=ref(''),open=ref(false),selected=ref<Row|null>(null),records=ref<Row[]>([]),reviews=ref<Row[]>([]),note=ref(''),photoIds=ref<string[]>([]),uploading=ref(false),rating=ref(5),reviewText=ref('')
const filtered=computed(()=>orders.value.filter(o=>!filter.value||o.STATUS===filter.value))
async function load(){loading.value=true;error.value='';try{orders.value=await api<Row[]>('/orders')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function detail(order:Row){if(await act(async()=>{[selected.value,records.value,reviews.value]=await Promise.all([api(`/orders/${order.ID}`),api<Row[]>(`/orders/${order.ID}/records`),api<Row[]>(`/orders/${order.ID}/reviews`)]);note.value='';photoIds.value=[];reviewText.value='';open.value=true}))return}
async function action(order:Row,action:string){if(busy.value)return;let body:unknown=undefined;try{if(action==='reject'){const result=await ElMessageBox.prompt('填写拒单原因','拒绝预约',{inputPattern:/\S/,inputErrorMessage:'请输入原因'});body={note:result.value}}else if(['cancel','pay','complete','confirm'].includes(action)){await ElMessageBox.confirm(action==='pay'?`模拟支付 ${money(order.PRICE_CENTS)}，不会产生真实扣款。`:`确认${{cancel:'取消预约',complete:'提交服务完成',confirm:'确认验收'}[action]}？`,'确认操作')}if(action==='complete')body={note:'喂养服务已完成，请主人验收'};busy.value=true;if(await act(()=>api(`/orders/${order.ID}/${action}`,'POST',body),'订单已更新')){await load();if(open.value&&selected.value?.ID===order.ID)await detail(order)}}catch{/* 取消确认 */}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file||!selected.value)return;if(file.size>5*1024*1024){ElMessage.error('请选择 5MB 以内的图片');input.value='';return}uploading.value=true;try{const body=new FormData();body.append('file',file);const response=await fetch(`/api/orders/${selected.value.ID}/photos`,{method:'POST',headers:{Authorization:`Bearer ${auth.token}`},body});const result=await response.json();if(!response.ok)throw new Error(result.message??'照片上传失败');photoIds.value.push(result.id);ElMessage.success('照片已上传，请保存喂养记录')}catch(e){ElMessage.error((e as Error).message)}finally{uploading.value=false;input.value=''}}
async function saveRecord(){if(!selected.value||busy.value)return;busy.value=true;const id=selected.value.ID;if(await act(()=>api(`/orders/${id}/records`,'POST',{note:note.value,photos:photoIds.value}),'喂养记录已保存'))await detail(selected.value);busy.value=false}
async function saveReview(){if(!selected.value||busy.value)return;busy.value=true;if(await act(()=>api(`/orders/${selected.value!.ID}/reviews`,'POST',{rating:rating.value,content:reviewText.value}),'评价已提交'))await detail(selected.value);busy.value=false}
async function complain(order:Row){try{const result=await ElMessageBox.prompt('请描述服务问题，管理员会查看并处理。','提交投诉',{inputType:'textarea',inputPattern:/\S/,inputErrorMessage:'请输入问题描述'});await act(()=>api(`/orders/${order.ID}/complaints`,'POST',{note:result.value}),'投诉已提交，可在投诉与反馈中查看')}catch{/* 取消 */}}
function photos(row:Row):string[]{try{return JSON.parse(row.PHOTOS??'[]')}catch{return[]}}
onMounted(load)
</script>
<template><PlatformLayout><div class="page-heading"><div><span class="eyebrow">EVERY VISIT MATTERS</span><h1>服务订单</h1><p>从预约到验收，查看每一次照顾的进度与记录。</p></div><el-button @click="load">刷新订单</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="business-card" v-loading="loading"><el-select v-model="filter" placeholder="全部状态" clearable class="status-filter"><el-option v-for="(label,state) in states" :key="state" :label="label" :value="state"/></el-select><el-empty v-if="!filtered.length" description="暂无匹配订单"/><article v-for="order in filtered" :key="order.ID" class="order-card"><div class="order-top"><span class="order-id">{{ String(order.ID).slice(0,8) }}</span><el-tag>{{ states[order.STATUS] }}</el-tag></div><div class="order-body"><div><h3>{{ order.SITTER_NAME }} · {{ order.PET_SNAPSHOT||'宠物上门服务' }}</h3><p>{{ date(order.STARTS_AT) }} 至 {{ date(order.ENDS_AT) }}</p><p class="long-text">{{ order.ADDRESS_SNAPSHOT }}</p></div><strong class="quote-price">{{ money(order.PRICE_CENTS) }}</strong></div><div class="card-actions"><el-button @click="detail(order)">详情与喂养记录</el-button><template v-if="auth.user?.role==='OWNER'"><el-button v-if="['PENDING','ACCEPTED'].includes(order.STATUS)&&order.PAYMENT_STATE!=='PAID'" :loading="busy" @click="action(order,'pay')">模拟支付</el-button><el-button v-if="['PENDING','ACCEPTED'].includes(order.STATUS)" text type="danger" :disabled="busy" @click="action(order,'cancel')">取消预约</el-button><el-button v-if="order.STATUS==='WAITING_CONFIRM'" type="primary" :loading="busy" @click="action(order,'confirm')">确认验收</el-button></template><template v-if="auth.user?.role==='SITTER'"><el-button v-if="order.STATUS==='PENDING'" type="primary" :loading="busy" @click="action(order,'accept')">接单</el-button><el-button v-if="order.STATUS==='PENDING'" text type="danger" :disabled="busy" @click="action(order,'reject')">拒单</el-button><el-button v-if="order.STATUS==='ACCEPTED'" type="primary" :loading="busy" @click="action(order,'start')">开始服务</el-button><el-button v-if="order.STATUS==='IN_PROGRESS'" type="primary" :loading="busy" @click="action(order,'complete')">提交完成</el-button></template><el-button text @click="complain(order)">投诉与反馈</el-button></div></article></section>
<el-dialog v-model="open" title="订单详情与喂养记录" width="min(760px, 94vw)" destroy-on-close><template v-if="selected"><el-descriptions :column="1" border><el-descriptions-item label="订单编号">{{ selected.ID }}</el-descriptions-item><el-descriptions-item label="状态">{{ states[selected.STATUS] }}</el-descriptions-item><el-descriptions-item label="预约时间">{{ date(selected.STARTS_AT) }} 至 {{ date(selected.ENDS_AT) }}</el-descriptions-item><el-descriptions-item label="服务内容">{{ selected.SERVICE_SNAPSHOT }}</el-descriptions-item><el-descriptions-item label="宠物及注意事项">{{ selected.PET_SNAPSHOT }}</el-descriptions-item><el-descriptions-item label="地址快照">{{ selected.ADDRESS_SNAPSHOT }}</el-descriptions-item><el-descriptions-item label="报价与模拟支付">{{ money(selected.PRICE_CENTS) }} · {{ {UNPAID:'未支付',PAID:'已模拟支付',REFUNDED:'已模拟退款'}[selected.PAYMENT_STATE as 'UNPAID'|'PAID'|'REFUNDED'] }}</el-descriptions-item><el-descriptions-item v-if="selected.CANCEL_REASON" label="关闭原因">{{ selected.CANCEL_REASON }}</el-descriptions-item></el-descriptions><h3>喂养记录</h3><p v-if="!records.length" class="muted">暂无喂养记录。</p><article v-for="record in records" :key="record.ID" class="record-card"><small>{{ date(record.CREATED_AT) }}</small><p class="long-text">{{ record.NOTE }}</p><div class="photo-grid"><PrivatePhoto v-for="photo in photos(record)" :key="photo" :id="photo"/></div></article><el-form v-if="auth.user?.role==='SITTER'&&selected.STATUS==='IN_PROGRESS'" label-position="top" @submit.prevent="saveRecord"><el-form-item label="添加喂养记录"><el-input v-model="note" type="textarea" :rows="3" maxlength="2000" placeholder="记录喂粮、换水、猫砂清理和宠物状态"/></el-form-item><label class="upload-button">{{ uploading?'正在上传…':'选择喂养照片（PNG / JPEG）' }}<input type="file" accept="image/png,image/jpeg" :disabled="uploading||photoIds.length>=6" @change="upload"/></label><p class="muted">已选择 {{ photoIds.length }} 张，每条记录最多 6 张，每张 5MB 以内。</p><el-button type="primary" native-type="submit" :loading="busy" :disabled="!note.trim()||uploading">保存喂养记录</el-button></el-form><h3>服务评价</h3><article v-for="review in reviews" :key="review.ID" class="record-card"><el-rate :model-value="review.RATING" disabled/><p>{{ review.CONTENT }}</p></article><el-form v-if="auth.user?.role==='OWNER'&&selected.STATUS==='COMPLETED'&&!reviews.length" label-position="top" @submit.prevent="saveReview"><el-rate v-model="rating"/><el-input v-model="reviewText" type="textarea" :rows="3" maxlength="1000" placeholder="说说这次服务体验"/><el-button class="spaced" type="primary" native-type="submit" :loading="busy" :disabled="!reviewText.trim()||!rating">提交评价</el-button></el-form></template></el-dialog></PlatformLayout></template>
